    private class GlyphPath(val data: String, val evenOdd: Boolean = false)

    private fun glyph(name: String, vararg paths: GlyphPath): ImageVector =
        ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 24f,
            viewportHeight = 24f,
        ).apply {
            for (p in paths) {
                addPath(
                    pathData = PathParser().parsePathString(p.data).toNodes(),
                    pathFillType = if (p.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                    fill = SolidColor(Color.Black),
                )
            }
        }.build()
}
